<div class="two"><form class="panel" method="post" action="/admin/templates/<?= (int) $t['id'] ?>"><?= csrf_field() ?><div class="panel-h"><span><?= e($t['name']) ?></span><?= $t['kind'] === 'system' ? badge('Automatic email', 'blue') : badge('Saved reply', 'green') ?></div><div class="panel-b form">
  <?= a_in('Name', 'name', $t['name']) ?><?= a_in('Subject', 'subject', $t['subject']) ?><?= a_in('Message', 'body', $t['body'], ['type' => 'textarea', 'rows' => 12, 'hint' => 'Use **bold**, [links](https://…) and - bullet lists. Placeholders such as {{name}} are replaced automatically.']) ?>
  <?= a_in('Send from mailbox (optional)', 'mailbox', $t['mailbox'] ?? '', ['type' => 'email', 'hint' => 'Leave blank to use the default sender for this type of email.']) ?>
  <div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn btn-primary btn-sm">Save template</button><?php if ($has_default): ?><button class="btn btn-ghost btn-sm" name="action" value="reset" data-confirm="Restore the original wording?">Restore default</button><?php endif; ?><?php if ($t['kind'] === 'canned'): ?><button class="btn btn-ghost btn-sm" name="action" value="delete" data-confirm="Delete this template?">Delete</button><?php endif; ?></div></div></form>
<div class="panel"><div class="panel-h">Preview (saved version)</div><iframe sandbox style="width:100%;height:640px;border:0" srcdoc="<?= e($preview) ?>" title="Preview"></iframe></div></div>
